def redact(value, sensitive):
    sensitive_lower = {s.lower() for s in sensitive}

    def copy(v):
        if isinstance(v, dict):
            result = {}
            for key, val in v.items():
                if isinstance(key, str) and key.lower() in sensitive_lower:
                    result[key] = "[REDACTED]"
                else:
                    result[key] = copy(val)
            return result

        if isinstance(v, list):
            return [copy(item) for item in v]

        return v

    return copy(value)
```

