from typing import Any

def merge(base: dict, overlay: dict) -> dict:
    def deep_copy(value: Any) -> Any:
        if isinstance(value, dict):
            return {key: deep_copy(val) for key, val in value.items()}
        if isinstance(value, list):
            return [deep_copy(val) for val in value]
        if isinstance(value, tuple):
            return tuple(deep_copy(val) for val in value)
        return value

    if not isinstance(base, dict):
        return deep_copy(overlay)
    if not isinstance(overlay, dict):
        return deep_copy(base)

    result = {key: deep_copy(value) for key, value in base.items()}
    for key, overlay_value in overlay.items():
        base_value = base.get(key)
        if key in base and isinstance(base_value, dict) and isinstance(overlay_value, dict):
            result[key] = merge(base_value, overlay_value)
        else:
