import copy

def merge(base, overlay):
    def _deep_copy(value):
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_deep_copy(v) for v in value]
        return value

    def _merge_dicts(base_dict, overlay_dict):
        result = {}
        for key, value in base_dict.items():
            result[key] = _deep_copy(value)
        for key, value in overlay_dict.items():
            copied_overlay = _deep_copy(value)
            existing = result.get(key)
            if isinstance(existing, dict) and isinstance(copied_overlay, dict):
                result[key] = _merge_dicts(existing, copied_overlay)
            else:
                result[key] = copied_overlay
        return result

    return _merge_dicts(base, overlay)

